{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-gOdLEZ/src/errors.js","content":"/**
 * The error the parser throws for any malformed line. The CLI turns it into
 * `error: line N: <reason>` on standard error.
 */
export class ParseError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

export function fail(line, reason) {
  throw new ParseError(line, reason)
}

export function joinPath(segments) {
  return segments.join('.')
}
"}

