{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-gOdLEZ/src/nodes.js","content":"/**
 * Node shapes used by the parser and the output formatters.
 *
 * - table:   { kind: 'table', value: Map<string, node>, headerLocked }
 * - array:   { kind: 'array', value: node[], isTableArray }
 * - string:  { kind: 'string', value: string }
 * - boolean: { kind: 'boolean', value: boolean }
 * - integer: { kind: 'integer', raw: string }   // decimal digits, JSON-ready
 * - float:   { kind: 'float', value: number }
 */

export function newTable(headerLocked = false) {
  return { kind: 'table', value: new Map(), headerLocked }
}

export function newArray(isTableArray = false) {
  return { kind: 'array', value: [], isTableArray }
}
"}

