{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-gOdLEZ/src/parser.js","content":"/**
 * Parses a configuration document (see the task specification) into a tree
 * of nodes as described in nodes.js. Throws a ParseError on the first
 * malformed line.
 */

import { fail, joinPath } from './errors.js'
import { newTable, newArray } from './nodes.js'

const NAME_CHAR = /[A-Za-z0-9_-]/
const INT_RE = /^[+-]?\d+(_\d+)*$/
const FLOAT_RE = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

class LineCtx {
  constructor(line) {
    this.line = line
    this.pos = 0
  }

  peek() {
    return this.pos < this.line.length ? this.line[this.pos] : undefined
  }

  eof() {
    return this.pos >= this.line.length
  }
}

function skipWs(ctx) {
  while (!ctx.eof() && (ctx.peek() === ' ' || ctx.peek() === '\t')) ctx.pos++
}

function skipWsComment(ctx) {
  while (!ctx.eof()) {
    const c = ctx.peek()
    if (c === ' ' || c === '\t') {
      ctx.pos++
      continue
    }
    if (c === '#' || c === ';') {
      ctx.pos = ctx.line.length
      return
    }
    break
  }
}

function parseBasicString(ctx, lineNo) {
  ctx.pos++ // opening quote
  let result = ''
  for (;;) {
    if (ctx.eof()) fail(lineNo, 'unterminated string')
    const c = ctx.line[ctx.pos]
    if (c === '"') {
      ctx.pos++
      return result
    }
    if (c === '\\') {
      ctx.pos++
      if (ctx.eof()) fail(lineNo, 'unterminated string')
      const e = ctx.line[ctx.pos]
      if (e === '"') { result += '"'; ctx.pos++ }
      else if (e === '\\') { result += '\\'; ctx.pos++ }
      else if (e === 'n') { result += '\n'; ctx.pos++ }
      else if (e === 't') { result += '\t'; ctx.pos++ }
      else if (e === 'r') { result += '\r'; ctx.pos++ }
      else if (e === '0') { result += '\0'; ctx.pos++ }
      else if (e === 'u') {
        const hex = ctx.line.slice(ctx.pos + 1, ctx.pos + 5)
        if (hex.length === 4 && /^[0-9A-Fa-f]{4}$/.test(hex)) {
          result += String.fromCharCode(parseInt(hex, 16))
          ctx.pos += 5
        } else {
          fail(lineNo, 'invalid escape \\u')
        }
      } else {
        fail(lineNo, `invalid escape \\${e}`)
      }
      continue
    }
    result += c
    ctx.pos++
  }
}

function parseLiteralString(ctx, lineNo) {
  ctx.pos++ // opening quote
  const start = ctx.pos
  const idx = ctx.line.indexOf("'", ctx.pos)
  if (idx === -1) fail(lineNo, 'unterminated string')
  const result = ctx.line.slice(start, idx)
  ctx.pos = idx + 1
  return result
}

function parseName(ctx) {
  if (ctx.eof()) return null
  const c = ctx.peek()
  if (c === '"') return parseBasicString(ctx, ctx.lineNo)
  if (c === "'") return parseLiteralString(ctx, ctx.lineNo)
  const start = ctx.pos
  while (!ctx.eof() && NAME_CHAR.test(ctx.peek())) ctx.pos++
  if (ctx.pos === start) return null
  return ctx.line.slice(start, ctx.pos)
}

function parseDottedName(ctx, lineNo) {
  skipWs(ctx)
  const first = parseName(ctx, lineNo)
  if (first === null) fail(lineNo, 'expected a name')
  const segments = [first]
  for (;;) {
    const save = ctx.pos
    skipWs(ctx)
    if (ctx.peek() === '.') {
      ctx.pos++
      skipWs(ctx)
      const next = parseName(ctx, lineNo)
      if (next === null) fail(lineNo, 'expected a name')
      segments.push(next)
    } else {
      ctx.pos = save
      break
    }
  }
  return segments
}

function normalizeInt(word) {
  const sign = word[0] === '-' ? '-' : ''
  const digits = word.replace(/^[+-]/, '').replace(/_/g, '')
  return BigInt(sign + digits).toString()
}

function parseValue(ctx, lineNo, basePath) {
  skipWsComment(ctx)
  if (ctx.eof()) fail(lineNo, 'expected a value')
  const c = ctx.peek()
  if (c === ',' || c === ']' || c === '}') fail(lineNo, 'expected a value')
  if (c === '"') return { kind: 'string', value: parseBasicString(ctx, lineNo) }
  if (c === "'") return { kind: 'string', value: parseLiteralString(ctx, lineNo) }
  if (c === '[') return parseArray(ctx, lineNo, basePath)
  if (c === '{') return parseInlineTable(ctx, lineNo, basePath)

  const start = ctx.pos
  while (!ctx.eof()) {
    const ch = ctx.peek()
    if (ch === ' ' || ch === '\t' || ch === ',' || ch === ']' || ch === '}') break
    ctx.pos++
  }
  const word = ctx.line.slice(start, ctx.pos)
  if (word === 'true') return { kind: 'boolean', value: true }
  if (word === 'false') return { kind: 'boolean', value: false }
  if (INT_RE.test(word)) return { kind: 'integer', raw: normalizeInt(word) }
  if (FLOAT_RE.test(word) && /[.eE]/.test(word)) {
    return { kind: 'float', value: Number(word.replace(/_/g, '')) }
  }
  fail(lineNo, `invalid value ${word}`)
}

function parseArray(ctx, lineNo, basePath) {
  ctx.pos++ // consume [
  skipWsComment(ctx)
  const items = []
  if (ctx.peek() === ']') {
    ctx.pos++
    return { kind: 'array', isTableArray: false, value: items }
  }
  for (;;) {
    items.push(parseValue(ctx, lineNo, basePath))
    skipWsComment(ctx)
    if (ctx.peek() === ',') {
      ctx.pos++
      skipWsComment(ctx)
      if (ctx.peek() === ']') { ctx.pos++; break }
      continue
    }
    if (ctx.peek() === ']') { ctx.pos++; break }
    fail(lineNo, 'unterminated array')
  }
  return { kind: 'array', isTableArray: false, value: items }
}

function assignInto(container, segments, basePath, value, lineNo) {
  let cur = container
  for (let i = 0; i < segments.length - 1; i++) {
    const seg = segments[i]
    let child = cur.value.get(seg)
    if (child === undefined) {
      child = newTable()
      cur.value.set(seg, child)
    } else if (child.kind === 'table') {
      // descend
    } else if (child.kind === 'array' && child.isTableArray) {
      child = child.value[child.value.length - 1]
    } else {
      fail(lineNo, `${joinPath(basePath.concat(segments.slice(0, i + 1)))} is not a table`)
    }
    cur = child
  }
  const last = segments[segments.length - 1]
  if (cur.value.has(last)) {
    fail(lineNo, `key ${joinPath(basePath.concat(segments))} is defined twice`)
  }
  cur.value.set(last, value)
}

function parseInlineTable(ctx, lineNo, basePath) {
  ctx.pos++ // consume {
  skipWsComment(ctx)
  const node = newTable()
  if (ctx.peek() === '}') {
    ctx.pos++
    return node
  }
  for (;;) {
    const segments = parseDottedName(ctx, lineNo)
    skipWsComment(ctx)
    if (ctx.peek() !== '=') fail(lineNo, 'expected = in an inline table')
    ctx.pos++
    skipWsComment(ctx)
    const value = parseValue(ctx, lineNo, basePath.concat(segments))
    assignInto(node, segments, basePath, value, lineNo)
    skipWsComment(ctx)
    if (ctx.peek() === ',') {
      ctx.pos++
      skipWsComment(ctx)
      continue
    }
    if (ctx.peek() === '}') { ctx.pos++; break }
    fail(lineNo, 'unterminated inline table')
  }
  return node
}

function walkForHeader(root, segments, lineNo) {
  let cur = root
  for (let i = 0; i < segments.length - 1; i++) {
    const seg = segments[i]
    let child = cur.value.get(seg)
    if (child === undefined) {
      child = newTable()
      cur.value.set(seg, child)
    } else if (child.kind === 'table') {
      // descend
    } else if (child.kind === 'array' && child.isTableArray) {
      child = child.value[child.value.length - 1]
    } else {
      fail(lineNo, `${joinPath(segments.slice(0, i + 1))} is not a table`)
    }
    cur = child
  }
  return cur
}

function processHeaderSemantics(state, segments, isArrayHeader, lineNo) {
  const parent = walkForHeader(state.root, segments, lineNo)
  const last = segments[segments.length - 1]
  if (isArrayHeader) {
    let arr = parent.value.get(last)
    if (arr === undefined) {
      arr = newArray(true)
      parent.value.set(last, arr)
    } else if (!(arr.kind === 'array' && arr.isTableArray)) {
      fail(lineNo, `${joinPath(segments)} is not an array of tables`)
    }
    const table = newTable()
    arr.value.push(table)
    state.current = table
    state.currentPath = segments.slice()
  } else {
    let tbl = parent.value.get(last)
    if (tbl === undefined) {
      tbl = newTable(true)
      parent.value.set(last, tbl)
    } else if (tbl.kind !== 'table') {
      fail(lineNo, `${joinPath(segments)} is not a table`)
    } else if (tbl.headerLocked) {
      fail(lineNo, `table ${joinPath(segments)} is defined twice`)
    } else {
      tbl.headerLocked = true
    }
    state.current = tbl
    state.currentPath = segments.slice()
  }
}

function processHeaderLine(line, lineNo, state) {
  const ctx = new LineCtx(line)
  ctx.pos = 1
  let isArray = false
  if (ctx.peek() === '[') { isArray = true; ctx.pos++ }
  skipWsComment(ctx)
  const segments = parseDottedName(ctx, lineNo)
  skipWsComment(ctx)
  if (ctx.peek() !== ']') fail(lineNo, 'unterminated table header')
  ctx.pos++
  if (isArray) {
    if (ctx.peek() !== ']') fail(lineNo, 'unterminated table header')
    ctx.pos++
  }
  skipWsComment(ctx)
  if (!ctx.eof()) fail(lineNo, 'trailing text after a table header')
  processHeaderSemantics(state, segments, isArray, lineNo)
}

function processKeyValueLine(line, lineNo, state, startPos) {
  const ctx = new LineCtx(line)
  ctx.pos = startPos
  const segments = parseDottedName(ctx, lineNo)
  skipWsComment(ctx)
  if (ctx.peek() !== '=') fail(lineNo, 'expected key = value')
  ctx.pos++
  skipWsComment(ctx)
  const value = parseValue(ctx, lineNo, state.currentPath.concat(segments))
  skipWsComment(ctx)
  if (!ctx.eof()) fail(lineNo, 'trailing text after a value')
  assignInto(state.current, segments, state.currentPath, value, lineNo)
}

function processLine(line, lineNo, state) {
  let idx = 0
  while (idx < line.length && (line[idx] === ' ' || line[idx] === '\t')) idx++
  if (idx === line.length) return
  const c = line[idx]
  if (c === '#' || c === ';') return
  if (line[0] === '[') {
    processHeaderLine(line, lineNo, state)
    return
  }
  processKeyValueLine(line, lineNo, state, idx)
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = newTable()
  const state = { root, current: root, currentPath: [] }

  for (let i = 0; i < lines.length; i++) {
    processLine(lines[i], i + 1, state)
  }

  return root
}
"}

