{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-gOdLEZ/src/output.js","content":"/**
 * Renders a parsed document tree (see nodes.js) as canonical JSON, or as a
 * flat `keys` listing.
 */

function compareCodePoints(a, b) {
  const ai = Array.from(a)
  const bi = Array.from(b)
  const len = Math.min(ai.length, bi.length)
  for (let i = 0; i < len; i++) {
    const ca = ai[i].codePointAt(0)
    const cb = bi[i].codePointAt(0)
    if (ca !== cb) return ca - cb
  }
  return ai.length - bi.length
}

function sortedKeys(map) {
  return [...map.keys()].sort(compareCodePoints)
}

function serialize(node, depth) {
  const indent = '  '.repeat(depth)
  const childIndent = '  '.repeat(depth + 1)
  switch (node.kind) {
    case 'table': {
      const keys = sortedKeys(node.value)
      if (keys.length === 0) return '{}'
      const lines = keys.map(
        (k) => `${childIndent}${JSON.stringify(k)}: ${serialize(node.value.get(k), depth + 1)}`
      )
      return `{\n${lines.join(',\n')}\n${indent}}`
    }
    case 'array': {
      const items = node.value
      if (items.length === 0) return '[]'
      const lines = items.map((it) => `${childIndent}${serialize(it, depth + 1)}`)
      return `[\n${lines.join(',\n')}\n${indent}]`
    }
    case 'string':
      return JSON.stringify(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    case 'integer':
      return node.raw
    case 'float':
      return JSON.stringify(node.value)
    default:
      throw new Error(`unknown node kind ${node.kind}`)
  }
}

export function toJson(root) {
  return `${serialize(root, 0)}\n`
}

function typeName(node) {
  return node.kind
}

function emit(node, path, out) {
  out.push(`${path} ${typeName(node)}`)
  if (node.kind === 'table') {
    for (const k of sortedKeys(node.value)) emit(node.value.get(k), `${path}.${k}`, out)
  } else if (node.kind === 'array') {
    node.value.forEach((item, i) => emit(item, `${path}[${i}]`, out))
  }
}

export function toKeys(root) {
  const out = []
  for (const k of sortedKeys(root.value)) emit(root.value.get(k), k, out)
  return out.length ? `${out.join('\n')}\n` : ''
}
